mapper.update:
UPDATE workflow_instance SET status = 'WAITING', current_step_id = #{nextStepId}, next_run_at = NULL,
	updated_at = now()
WHERE instance_id = #{instanceId}

UPDATE workflow_instance SET status = 'WAITING', current_step_id = #{nextStepId}, next_run_at = #{nextRunAt},
	updated_at = now()
WHERE instance_id = #{instanceId}

UPDATE workflow_instance SET status = 'WAITING', retry_count = retry_count + 1, next_run_at = #{nextRunAt},
	last_error = #{errorMessage}, updated_at = now()
WHERE instance_id = #{instanceId}
